/* @autogenerated */
package net.civeira.phylax.feature.observe.ingest;

import java.io.PrintWriter;
import java.io.StringWriter;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.TimeUnit;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import io.opentelemetry.api.common.AttributeKey;
import io.opentelemetry.api.common.Attributes;
import io.opentelemetry.api.trace.StatusCode;
import io.opentelemetry.sdk.logs.data.LogRecordData;
import io.opentelemetry.sdk.trace.data.SpanData;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.config.ObservabilitySettings;
import net.civeira.phylax.feature.observe.config.ObserveSettings;
import net.civeira.phylax.feature.observe.source.SourceRegistry;
import net.civeira.phylax.feature.observe.source.SourceRegistry.Source;
import net.civeira.phylax.feature.observe.store.Levels;
import net.civeira.phylax.feature.observe.store.ObsLog;
import net.civeira.phylax.feature.observe.store.ObsSpan;

/**
 * Turns the OpenTelemetry data (own or received by the OTLP collector) into stored events, applying
 * the source rules: attribution, minimum level and trace sampling, and masking the attributes whose
 * key is in the scrub fields (global of observability-config and of the source).
 */
@ApplicationScoped
@RequiredArgsConstructor
public class TelemetryMapper {

  private static final AttributeKey<String> SERVICE = AttributeKey.stringKey("service.name");

  /** Value stored instead of a masked attribute. */
  public static final String MASKED = "[masked]";

  private final SourceRegistry registry;
  private final ObservabilitySettings settings;
  private final @ConfigProperty(name = "app.observe.self",
      defaultValue = "true") boolean observeSelf;
  private final @ConfigProperty(name = "app.observe.self-source",
      defaultValue = "phylax-api") String selfSource;

  /**
   * Source of an event.
   *
   * @param fromRequest the event arrived by the OTLP collector (not produced by this process)
   * @param keySource source of the X-Observe-Key of the request, if any
   */
  public Optional<Source> resolve(final boolean fromRequest, final Optional<Source> keySource,
      final Attributes resource) {
    Optional<Source> source;
    if (fromRequest) {
      source = keySource.isPresent() ? keySource
          : registry.byCode(null == resource ? null : resource.get(SERVICE));
    } else {
      source = observeSelf ? registry.byCode(selfSource) : Optional.empty();
    }
    return source.filter(Source::accepting);
  }

  public Optional<ObsSpan> span(final Source source, final SpanData span) {
    boolean error = span.getStatus().getStatusCode() == StatusCode.ERROR;
    if (!error && !sampled(span.getTraceId(), source.sampleRate())) {
      return Optional.empty();
    }
    String parent = parentId(span);
    long start = TimeUnit.NANOSECONDS.toMillis(span.getStartEpochNanos());
    double duration = (span.getEndEpochNanos() - span.getStartEpochNanos()) / 1_000_000.0;
    return Optional.of(new ObsSpan(start, source.code(), span.getTraceId(), span.getSpanId(),
        parent, span.getName(), span.getKind().name(), duration,
        span.getStatus().getStatusCode().name(), scrub(source, attributes(span.getAttributes()))));
  }

  @SuppressWarnings("deprecation")
  public Optional<ObsLog> log(final Source source, final LogRecordData record) {
    String level = null != record.getSeverityText() && !record.getSeverityText().isBlank()
        ? Levels.normalize(record.getSeverityText())
        : Levels.fromSeverity(record.getSeverity().getSeverityNumber());
    if (!Levels.atLeast(level, source.minLevel())) {
      return Optional.empty();
    }
    long ts = TimeUnit.NANOSECONDS
        .toMillis(record.getTimestampEpochNanos() > 0 ? record.getTimestampEpochNanos()
            : record.getObservedTimestampEpochNanos());
    if (ts <= 0) {
      ts = System.currentTimeMillis();
    }
    String message = null == record.getBody() ? "" : record.getBody().asString();
    String traceId =
        record.getSpanContext().isValid() ? record.getSpanContext().getTraceId() : null;
    String spanId = record.getSpanContext().isValid() ? record.getSpanContext().getSpanId() : null;
    Map<String, Object> attrs = attributes(record.getAttributes());
    Object error = attrs.remove("exception.stacktrace");
    String scope = null == record.getInstrumentationScopeInfo() ? null
        : record.getInstrumentationScopeInfo().getName();
    return Optional.of(new ObsLog(ts, source.code(), level, scope, message, traceId, spanId,
        null == error ? null : String.valueOf(error), scrub(source, attrs)));
  }

  /** Log of this process (the JUL / logback handler). */
  public Optional<ObsLog> ownLog(final long ts, final String level, final String logger,
      final String message, final Throwable thrown, final String traceId, final String spanId) {
    if (!observeSelf) {
      return Optional.empty();
    }
    return registry.byCode(selfSource).filter(Source::accepting)
        .filter(source -> Levels.atLeast(level, source.minLevel()))
        .map(source -> new ObsLog(ts, source.code(), Levels.normalize(level), logger, message,
            traceId, spanId, null == thrown ? null : stack(thrown), Map.of()));
  }

  public String selfSource() {
    return selfSource;
  }

  public boolean observeSelf() {
    return observeSelf;
  }

  /**
   * Parent span; the spans received by the OTLP collector may come without parent context, only
   * with the parent id (empty or all zeros for a root span).
   */
  static String parentId(final SpanData span) {
    io.opentelemetry.api.trace.SpanContext context = span.getParentSpanContext();
    if (null != context) {
      return context.isValid() ? context.getSpanId() : "";
    }
    String id = span.getParentSpanId();
    return null == id || id.isEmpty() || id.chars().allMatch(c -> c == '0') ? "" : id;
  }

  /** Deterministic by trace: the whole trace is kept or dropped in every source. */
  static boolean sampled(final String traceId, final int rate) {
    if (rate >= 100) {
      return true;
    }
    if (rate <= 0 || null == traceId) {
      return false;
    }
    return Math.floorMod(traceId.hashCode(), 100) < rate;
  }

  /**
   * Masks the attributes whose key, or one of its dotted segments, is a scrub field: with
   * {@code authorization}, also {@code http.request.header.authorization}.
   */
  Map<String, Object> scrub(final Source source, final Map<String, Object> attrs) {
    Set<String> global = settings.current().scrubFields();
    Set<String> own = source.scrubFields();
    if (attrs.isEmpty() || (global.isEmpty() && own.isEmpty())) {
      return attrs;
    }
    attrs.replaceAll((key, value) -> masked(key, global, own) ? MASKED : value);
    return attrs;
  }

  static boolean masked(final String key, final Set<String> global, final Set<String> own) {
    String normalized = ObserveSettings.normalize(key);
    if (global.contains(normalized) || own.contains(normalized)) {
      return true;
    }
    for (String segment : normalized.split("\\.")) {
      if (global.contains(segment) || own.contains(segment)) {
        return true;
      }
    }
    return false;
  }

  private static Map<String, Object> attributes(final Attributes attributes) {
    Map<String, Object> result = new LinkedHashMap<>();
    if (null != attributes) {
      attributes.forEach((key, value) -> result.put(key.getKey(), value));
    }
    return result;
  }

  private static String stack(final Throwable thrown) {
    StringWriter writer = new StringWriter();
    thrown.printStackTrace(new PrintWriter(writer));
    return writer.toString();
  }
}
